SELECT F.NOME, (SELECT COUNT(DISTINCT L.VIDEO_ID) FROM LIVROS_INDICADOS L LEFT JOIN LIVROS_NOMES N ON N.NOME = L.TITULO COLLATE utf8mb4_0900_ai_ci LEFT JOIN LIVROS_CATALOGO LC ON LC.ID = N.CATALOGO_ID WHERE (COALESCE(LC.TITULO, L.TITULO) COLLATE utf8mb4_0900_ai_ci = F.NOME OR COALESCE(LC.TITULO, L.TITULO) COLLATE utf8mb4_0900_ai_ci IN (SELECT O.NOME COLLATE utf8mb4_0900_ai_ci FROM OBRA_DE O WHERE O.OBRA COLLATE utf8mb4_0900_ai_ci = F.NOME))) VIDEOS, (SELECT MAX(COALESCE(LC.AUTOR, L.AUTOR)) FROM LIVROS_INDICADOS L LEFT JOIN LIVROS_NOMES N ON N.NOME = L.TITULO COLLATE utf8mb4_0900_ai_ci LEFT JOIN LIVROS_CATALOGO LC ON LC.ID = N.CATALOGO_ID WHERE (COALESCE(LC.TITULO, L.TITULO) COLLATE utf8mb4_0900_ai_ci = F.NOME OR COALESCE(LC.TITULO, L.TITULO) COLLATE utf8mb4_0900_ai_ci IN (SELECT O.NOME COLLATE utf8mb4_0900_ai_ci FROM OBRA_DE O WHERE O.OBRA COLLATE utf8mb4_0900_ai_ci = F.NOME))) AUTOR FROM ITENS_FAVORITOS F WHERE F.TIPO = '{{tipo}}' ORDER BY F.NOME